/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { envelope, orgResource, requireFound } from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}
"use server";

/**
 * Soft-deletes an organization after slug confirmation.
 *
 * Owner D. `confirmSlug` is the "type the name to continue" guard; it is
 * compared against the stored slug rather than trusted, so a stale form cannot
 * delete a renamed organization.
 *
 * Must call (do not reimplement): deleteOrganizationSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  deleteOrganizationSchema,
  type DeleteOrganizationInput,
} from "@/schemas/organization";
import { deleteOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";
import { revalidatePath } from "next/cache";

const run = withAction<typeof deleteOrganizationSchema, Organization>(
  deleteOrganizationSchema,
  async (raw, actor) => {
    const input = raw as DeleteOrganizationInput;

    if (!can(actor, "org:delete", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:delete");
    }

    const organization = await deleteOrganization(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    revalidatePath("/orgs");
    return organization;
  },
  { revalidate: ["organization"], cacheProfile: "minutes" },
);

export async function deleteOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}
/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}
/**
 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
 *
 * Must call (do not reimplement): assertOrgScope
 */
import { hashToken, randomToken } from "@/lib/hash";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import { toIsoTimestamp } from "@/types/common";
import type { SwitchOrgInput } from "@/schemas/session";
import type { IsoTimestamp, UserId } from "@/types/common";
import type { Actor, SessionPrincipal } from "@/types/member";

/** How long a freshly issued session cookie stays valid. */
const SESSION_TTL_DAYS = 30;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login.
 */
export async function createSessionToken(
  userId: UserId,
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
  );

  await sessionRepo.createSession(userId, hashToken(token), expiresAt);

  return { token, expiresAt };
}

export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

/**
 * The bridge between "who is logged in" and "what may they do here": given a
 * principal and the org slug in the URL, produce the `Actor` every service
 * method takes, or `null` when the user is not a member of that org.
 *
 * The `assertOrgScope` call at the end looks redundant — the actor was just
 * built from that org — but it is the invariant this whole layer exists to
 * uphold, and it catches a mis-wired membership lookup immediately.
 */
export async function resolveActorForOrg(
  principal: SessionPrincipal,
  orgSlug: string,
): Promise<Actor | null> {
  const org = await orgRepo.findOrgBySlug(orgSlug);
  if (!org) return null;

  const member = await memberRepo.findMember(org.id, principal.userId);
  if (!member || member.status !== "active") return null;

  const actor: Actor = {
    userId: principal.userId,
    orgId: org.id,
    role: member.role,
  };

  assertOrgScope(actor, org.id);

  await memberRepo.touchLastSeen(
    org.id,
    principal.userId,
    toIsoTimestamp(new Date()),
  );

  return actor;
}

/**
 * Switches the org a session defaults to. Membership is re-checked here so a
 * removed member cannot pin their cookie to an org they left.
 *
 * `SessionPrincipal` carries no session id, so the write to `sessions.
 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
 * Action, which still holds the cookie. This method owns the authorization
 * half of the switch.
 */
export async function switchActiveOrg(
  principal: SessionPrincipal,
  input: SwitchOrgInput,
): Promise<void> {
  const member = await memberRepo.findMember(input.orgId, principal.userId);
  if (!member || member.status !== "active") {
    throw new Error("You are not a member of that organization");
  }

  const orgs = await orgRepo.listOrgsForUser(principal.userId);
  const target = orgs.find((org) => org.id === input.orgId);
  if (!target) throw new Error("You are not a member of that organization");

  assertOrgScope(
    { userId: principal.userId, orgId: input.orgId, role: member.role },
    target.id,
  );
}

/**
 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
 * exposes no session id, so the sweep is what actually clears the row, and the
 * cookie is dropped by the caller either way.
 */
export async function destroySession(token: string): Promise<void> {
  const principal = await resolveSession(token);
  if (!principal) return;

  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
}
/**
 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
 */
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { envelope, orgResource, requireFound } from "./_support";
import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
import type { InvitationId, UserId } from "@/types/common";
import type { Actor, Invitation, Member } from "@/types/member";

/** Token bucket protecting the invite mailer from being used as a spam relay. */
const INVITE_BUCKET = "member:invite";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

export async function inviteMember(
  actor: Actor,
  input: InviteMemberInput,
): Promise<Invitation> {
  const [invitation] = await inviteMembers(actor, {
    orgId: input.orgId,
    invites: [{ email: input.email, role: input.role }],
  });

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) +
    (await invitationRepo.countPendingInvitations(input.orgId));

  if (
    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
  ) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const invitations: Invitation[] = [];

  for (const invite of input.invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const existing = await memberRepo.findMember(invitation.orgId, userId);
  if (existing) return existing;

  const member = await memberRepo.insertMember(
    invitation.orgId,
    userId,
    invitation.role,
    invitation.invitedBy,
  );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    toIsoTimestamp(new Date()),
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo
      .listPendingInvitations(actor.orgId)
      .then((rows) => rows.find((row) => row.id === invitationId) ?? null),
    "Invitation",
    invitationId,
  );

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: previous.role === "owner" ? "admin" : previous.role,
  });
}

/**
 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 *
 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
import { sendEmail } from "@/server/services/email-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Organization } from "@/types/organization";

const ORG_BATCH = 50;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("digest-email-job");

/**
 * One pass per scheduler tick. Each org is only processed during the UTC hour
 * it configured, so a tick that runs every few minutes still sends exactly one
 * digest per day per recipient.
 */
export async function runDigestEmailJob(now: Date): Promise<JobResult> {
  return runJob("digest-email", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || !shouldRunForOrg(org, now)) continue;

      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;

      const windowEnd = toIsoTimestamp(now);
      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));

      for (const recipientId of await listDigestRecipients(orgId)) {
        try {
          const bundle = await buildDigest(
            orgId,
            recipientId,
            windowStart,
            windowEnd,
          );
          if (!bundle) continue;

          const recipient = await userRepo.findUserById(recipientId);
          if (!recipient) continue;

          const rendered = await renderDigest(bundle, recipient);
          await sendEmail({ to: recipient.email, ...rendered });

          // Once digested, these notifications are no longer "unread" — this
          // is what keeps a later run inside the same window from sending
          // the same digest twice.
          for (const entry of bundle.entries) {
            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
          }

          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("digest failed", {
            orgId,
            recipientId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}

/**
 * True during the org's configured digest hour. Exported because the schedule
 * decision is worth testing on its own, without a database.
 */
export function shouldRunForOrg(org: Organization, now: Date): boolean {
  if (org.archivedAt !== null) return false;
  return now.getUTCHours() === org.settings.digestHourUtc;
}
/**
 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
 *
 * Must call (do not reimplement): emit, shouldFilterArchived
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { shouldFilterArchived } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one pass sweeps. */
const ORG_BATCH = 50;

/** Archived issues are never overdue — an archived issue has no due date. */
const LIVE_ONLY = {} as const;

const logger = createLogger("overdue-issue-job");

/**
 * Issues already announced this process's lifetime. A later sweep still
 * finds a still-open, still-overdue issue — this is what keeps the job from
 * re-emitting `issue.overdue` for it on every pass.
 */
const reported = new Set<string>();

/** Test-only: clears the reported set so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  reported.clear();
}

/**
 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
 * no notification logic: it announces the fact, and whoever cares (in-app
 * alerts, the digest, webhooks) reacts on the bus.
 */
export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
  return runJob("overdue-issues", async (result) => {
    if (!shouldFilterArchived(LIVE_ONLY)) {
      logger.warn("archive scope misconfigured; skipping sweep", {});
      return;
    }

    const stamp = toIsoTimestamp(now);
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

      for (const issue of overdue) {
        if (issue.dueAt === null) continue;
        if (reported.has(issue.id)) continue;

        try {
          await emit("issue.overdue", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            issueId: issue.id,
            projectId: issue.projectId,
            dueAt: issue.dueAt,
            assigneeId: issue.assigneeId,
          });
          reported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}
/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const projects = await projectRepo.listProjects({
      orgId,
      limit: PAGE_SIZE,
      cursor: null,
    });

    for (const project of projects.items) {
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    const issues = await issueRepo.listIssues({
      orgId,
      limit: PAGE_SIZE,
      cursor: null,
    });

    for (const issue of issues.items) {
      try {
        await indexIssue(orgId, issue);
        result.processed += 1;

        const comments = await commentRepo.listComments({
          orgId,
          issueId: issue.id,
          includeArchived: false,
          limit: PAGE_SIZE,
          cursor: null,
        });

        for (const comment of comments.items) {
          await indexComment(orgId, comment);
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index issue", {
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Downgrades organizations whose trial ended and emits `billing.plan_changed`.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Where an expired trial lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("trial-expiry-job");

/**
 * Moves expired trials down to the free plan and announces the change so the
 * audit log and any webhook subscriber see it.
 *
 * A tenant that outgrew the free limits during the trial is left alone and
 * logged instead: silently downgrading them would put their workspace over
 * quota, and every subsequent write would fail with no explanation.
 */
export async function runTrialExpiryJob(now: Date): Promise<JobResult> {
  return runJob("trial-expiry", async (result) => {
    const stamp = toIsoTimestamp(now);
    const expiring = await subscriptionRepo.listTrialsEndingBefore(stamp);
    const freeLimits = getPlanLimits(FALLBACK_PLAN);

    for (const subscription of expiring) {
      const orgId = subscription.orgId as OrgId;
      const usage = await usageRepo.getUsage(orgId);

      if (
        usage.seatsUsed > freeLimits.seats ||
        usage.projectsUsed > freeLimits.projects
      ) {
        result.failed += 1;
        logger.warn("trial expired but tenant is over the free plan", {
          orgId,
          seats: usage.seatsUsed,
          projects: usage.projectsUsed,
        });
        continue;
      }

      await subscriptionRepo.updateSubscriptionPlan(
        orgId,
        FALLBACK_PLAN,
        subscription.interval,
      );

      await emit("billing.plan_changed", {
        orgId,
        actorId: null,
        occurredAt: stamp,
        from: subscription.plan,
        to: FALLBACK_PLAN,
      });

      result.processed += 1;
    }
  });
}
/**
 * Recomputes `organization_usage` so plan-limit checks stay accurate after bulk changes.
 *
 * Must call (do not reimplement): recomputeUsage
 */
import { createLogger } from "@/lib/logger";
import * as usageRepo from "@/server/repositories/usage-repository";
import { recomputeUsage } from "@/server/services/usage-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** Organizations recounted per pass; the list is oldest-measured first. */
const ORG_BATCH = 25;

const logger = createLogger("usage-rollup-job");

/**
 * The correction pass for the incremental deltas `UsageService` applies on the
 * write path. Those deltas are cheap but drift — an aborted transaction, a
 * cascade that archived more rows than the event reported — and a quota check
 * is only as trustworthy as the counter behind it.
 */
export async function runUsageRollupJob(now: Date): Promise<JobResult> {
  return runJob("usage-rollup", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      try {
        const usage = await recomputeUsage(orgId);
        result.processed += 1;

        logger.debug("usage recomputed", {
          orgId,
          seats: usage.seatsUsed,
          projects: usage.projectsUsed,
          issues: usage.issuesUsed,
          at: now.toISOString(),
        });
      } catch (error) {
        result.failed += 1;
        logger.error("usage rollup failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.
 *
 * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload
 */
import { getPlanLimits } from "@/config/plan-limits";
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { signPayload } from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** How many deliveries one pass claims. */
const CLAIM_BATCH = 25;

/** Attempts after which a delivery is marked failed for good. */
const MAX_ATTEMPTS = 6;

const logger = createLogger("webhook-delivery-job");

/**
 * Delivers each claimed row. There is no outbound HTTP in Taskflow — the
 * corpus builds and runs offline — so "delivery" means computing the
 * signature the receiver would verify and logging the attempt. The retry
 * bookkeeping around it is the part that has to be right.
 */
export async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {
  return runJob("webhook-delivery", async (result) => {
    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);

    for (const delivery of claimed) {
      const orgId = delivery.orgId as OrgId;

      if (!(await orgAllowsWebhooks(orgId))) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "webhooks are not included in this organization's plan",
        );
        result.failed += 1;
        continue;
      }

      if (delivery.attempts > MAX_ATTEMPTS) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          `giving up after ${delivery.attempts} attempts`,
        );
        result.failed += 1;
        continue;
      }

      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
        (row) => row.id === delivery.endpointId,
      );

      if (!endpoint || !endpoint.enabled) {
        await webhookRepo.markDeliveryFailed(
          orgId,
          delivery.id,
          "endpoint is missing or disabled",
        );
        result.failed += 1;
        continue;
      }

      const signature = signPayload(endpoint.secret, delivery.payload);

      logger.info("webhook delivered", {
        deliveryId: delivery.id,
        endpoint: endpoint.url,
        eventType: delivery.eventType,
        signature: signature.slice(0, 16),
        backoffMs: backoffMs(delivery.attempts),
      });

      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));
      result.processed += 1;
    }
  });
}

/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */
export function backoffMs(attempts: number): number {
  if (attempts <= 0) return 0;
  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);
}

async function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return false;

  if (getPlanLimits(org.plan).webhooks <= 0) return false;
  return isEnabled("webhooks", buildFlagContext(null, org));
}
/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Only the search documents are actually dropped here — the issue rows stay,
 * because the audit log still points at them — while the audit rows past the
 * window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      const archived = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: null,
        includeArchived: true,
      });

      for (const issue of archived.items) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Subscription rows; one active row per organization.
 */
import { and, eq, isNotNull, lte, ne } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, subscriptions } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toSubscription } from "./_mappers";
import type { BillingInterval, PlanId, Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

export async function findSubscription(
  orgId: OrgId,
): Promise<Subscription | null> {
  const row = getDb()
    .select()
    .from(subscriptions)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .get();
  return row ? toSubscription(row) : null;
}

/** New organizations start on a trial period rather than an active plan. */
export async function insertSubscription(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const periodEnd = toIsoTimestamp(
    new Date(now.getTime() + TRIAL_DAYS * MS_PER_DAY),
  );

  const row = getDb()
    .insert(subscriptions)
    .values({
      id: newId(),
      orgId,
      plan,
      interval,
      status: plan === "free" ? "active" : "trialing",
      seats: 1,
      currentPeriodStart: stamp,
      currentPeriodEnd: periodEnd,
      cancelAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toSubscription(row);
}

/** A plan change ends the trial: the org has made a deliberate choice. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({ plan, interval, status: "active", updatedAt: stamp })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

export async function updateSeatCount(
  orgId: OrgId,
  seats: number,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ seats, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** `cancelAt === null` reactivates a subscription scheduled for cancellation. */
export async function cancelSubscription(
  orgId: OrgId,
  cancelAt: IsoTimestamp | null,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      cancelAt,
      status: cancelAt === null ? "active" : "canceled",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
export async function listTrialsEndingBefore(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select()
    .from(subscriptions)
    .where(
      and(
        eq(subscriptions.status, "trialing"),
        isNotNull(subscriptions.currentPeriodEnd),
        lte(subscriptions.currentPeriodEnd, before),
        ne(subscriptions.plan, "free"),
      ),
    )
    .all();

  return rows.map(toSubscription);
}
import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are never physically removed — they get an
 * `archived_at` timestamp. Repositories must express "live rows only" through
 * these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents.
 */

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}

/** The column patch that archives a row. */
export function archivePatch(now: Date = new Date()): {
  archivedAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
} {
  const stamp = toIsoTimestamp(now);
  return { archivedAt: stamp, updatedAt: stamp };
}

/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}
/**
 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
 * affected tags.
 *
 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
 * things each one must do — validate, authenticate, translate errors,
 * revalidate — happen in exactly one place.
 *
 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
 */

import { getActor, requireActorFor } from "@/lib/actor";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { ZodType } from "zod";
import { UnauthorizedActionError } from "./action-errors";

/** The body of an action: already-validated input plus the resolved principal. */
export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;

export type ActionOptions = {
  /**
   * When `true` (the default) the organization is taken from the parsed input —
   * either an `orgSlug` or an `orgId` field. When `false` the action does not
   * name an organization and the session's active org is used instead.
   */
  requireOrg?: boolean;
  /** Static cache tags invalidated once the handler resolves. */
  revalidate?: readonly string[];
  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
  cacheProfile?: string;
};

type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };

/**
 * Resolves the actor for one action call.
 *
 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
 * instead resolve through `requireActorFor()`.
 */
async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
  if (fromInput && typeof input === "object" && input !== null) {
    const record = input as OrgBearingInput;
    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
      return getActor(record.orgSlug);
    }
    if (typeof record.orgId === "string" && record.orgId.length > 0) {
      return requireActorFor(record.orgId as OrgId);
    }
  }

  const principal = await getSessionPrincipal();
  if (principal === null || principal.activeOrgId === null) {
    throw new UnauthorizedActionError();
  }
  return requireActorFor(principal.activeOrgId);
}

/** Adds the monotonic token `useActionState` uses to tell two results apart. */
function stamp<T>(result: ActionResult<T>): ActionResult<T> {
  const submittedAt = new Date().toISOString();
  return result.ok
    ? { ok: true, data: result.data, submittedAt }
    : { ok: false, error: result.error, submittedAt };
}

export function withAction<TSchema extends ZodType, TData>(
  schema: TSchema,
  handler: ActionHandler,
  options: ActionOptions = {},
): (raw: unknown) => Promise<ActionResult<TData>> {
  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
    const parsed = schema.safeParse(raw);
    if (!parsed.success) {
      return stamp(toActionResult(parsed.error));
    }

    try {
      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
      const data = (await handler(parsed.data, actor)) as TData;

      const tags = options.revalidate ?? [];
      if (tags.length > 0) {
        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
      }

      return stamp({ ok: true, data });
    } catch (error) {
      return stamp(toActionResult(error));
    }
  };
}
import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

